const chainOf = (product: string) => data.chains.find((c) => c.product === product)

const expandBasis = (item: string): string => {
  const m = item.match(/^(.+?)第\s*([\d、]+)\s*步$/)
  if (m) {
    const chain = chainOf(m[1].trim())
    if (chain) {
      return m[2]
        .split("、")
        .map((n) => {
          const step = chain.steps.find((s) => s.no === Number(n))
          return step ? `${chain.product} 第 ${step.no} 步 · ${step.screen}` : item
        })
        .join(";")
    }
  }
  const issue = data.issues.find((i) => i.id === item)
  if (issue) return `${issue.id} ${issue.title}`
  return item
}
